def process(load_biomed_xlsx):
    import re
    df = load_biomed_xlsx
    sub = df[df['__sheet']=='D-SE-acetyl']
    if sub.shape[0]==0:
        sub = pd.concat([df[df['__sheet']=='D-SE-acetyl'], df[df['Description'].str.contains('acetyl', case=False, na=False)]])
    cols = ['Gene','ID','Feature','Description','REF']
    tokens = set()
    stop = {'significant','genes','by','acetylproteomics','in','figure','1','readme','nan','na','none'}
    pat_split = re.compile(r'[;,/|\s]+')
    pat_site = re.compile(r'-(?:[A-Za-z]?\d+|[A-Za-z]\d+)$')
    for _, row in sub[cols].fillna('').iterrows():
        combined = ' '.join(row.values.astype(str))
        for t in pat_split.split(combined):
            t = t.strip().strip('"\'')
            if not t:
                continue
            t_low = t.lower()
            if t_low in stop:
                continue
            t = pat_site.sub('', t)
            t = t.strip()
            if len(t) < 2 or len(t) > 30:
                continue
            if t.isdigit():
                continue
            if not re.search('[A-Za-z]', t):
                continue
            # filter out words with lowercase letters only
            if t.islower():
                continue
            tokens.add(t)
    genes = sorted(tokens)
    return pd.DataFrame({'significant_gene':genes})

def process(load_biomed_xlsx):
    import re
    df = load_biomed_xlsx
    sel = (df.get('__sheet') == 'D-SE-acetyl') | df.get('Description', '').str.contains('acetyl', case=False, na=False) | df.get('Sheet', '').str.contains('acetyl', case=False, na=False)
    sub = df[sel]
    cols = ['Gene', 'ID', 'Feature', 'Description', 'REF']
    tokens = []
    for col in cols:
        if col not in sub.columns:
            continue
        for val in sub[col].dropna().astype(str):
            parts = re.split(r'[;,|/\\\s]+', val)
            for part in parts:
                t = part.strip()
                if not t:
                    continue
                t = re.sub(r'[-_]\s*$', '', t)
                t = re.sub(r'[-_][A-Za-z]\d+.*$', '', t)
                t = t.strip()
                if not t:
                    continue
                if t.lower().startswith('signif') or t.lower().startswith('na'):
                    continue
                if len(t) < 2 or len(t) > 20:
                    continue
                if not re.search(r'[A-Za-z]', t):
                    continue
                tokens.append(t)
    seen = set()
    out = []
    for t in tokens:
        if t not in seen:
            seen.add(t)
            out.append(t)
    import pandas as pd
    return pd.DataFrame({'significant_gene': out})

